{"implementation":"def solve(case):
    word_indices = case["word_token_indices"]
    word_labels = case["word_labels"]
    kept_indices = []
    token_labels = []
    for idx_list, label in zip(word_indices, word_labels):
        if label == 1:
            kept_indices.extend(idx_list)
            token_labels.extend([label] * len(idx_list))
    return {"kept_indices": kept_indices, "token_labels": token_labels}"}
